package files

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
)

// BlobStore keeps uploaded file contents on disk under
// <dataDir>/uploads/<projectID>/<random>.blob. Names are generated by the
// server, so user-supplied paths never influence where data is written.
type BlobStore struct {
	dataDir string
}

// NewBlobStore returns a BlobStore rooted at dataDir.
func NewBlobStore(dataDir string) *BlobStore { return &BlobStore{dataDir: dataDir} }

// storagePathRe matches storage paths produced by Write. Anything else read
// from the database is refused, so a tampered row cannot point elsewhere.
var storagePathRe = regexp.MustCompile(`^uploads/[1-9][0-9]{0,18}/[0-9a-f]{32}\.blob$`)

var errBadStoragePath = errors.New("files: invalid storage path")

// Write stores data for projectID and returns its storage path (relative to
// the data directory, slash-separated).
func (b *BlobStore) Write(projectID int64, data []byte) (string, error) {
	dir := b.projectDir(projectID)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", fmt.Errorf("create upload directory: %w", err)
	}
	var id [16]byte
	if _, err := rand.Read(id[:]); err != nil {
		return "", err
	}
	name := hex.EncodeToString(id[:]) + ".blob"
	f, err := os.OpenFile(filepath.Join(dir, name), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return "", fmt.Errorf("create blob: %w", err)
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		os.Remove(f.Name())
		return "", fmt.Errorf("write blob: %w", err)
	}
	if err := f.Close(); err != nil {
		os.Remove(f.Name())
		return "", fmt.Errorf("close blob: %w", err)
	}
	return "uploads/" + strconv.FormatInt(projectID, 10) + "/" + name, nil
}

// Open opens a stored blob for reading.
func (b *BlobStore) Open(storagePath string) (*os.File, error) {
	full, err := b.resolve(storagePath)
	if err != nil {
		return nil, err
	}
	return os.Open(full)
}

// Read returns up to max bytes of a stored blob and whether it was truncated.
func (b *BlobStore) Read(storagePath string, max int64) ([]byte, bool, error) {
	f, err := b.Open(storagePath)
	if err != nil {
		return nil, false, err
	}
	defer f.Close()
	data, err := io.ReadAll(io.LimitReader(f, max+1))
	if err != nil {
		return nil, false, err
	}
	if int64(len(data)) > max {
		return data[:max], true, nil
	}
	return data, false, nil
}

// Remove deletes a stored blob. A missing blob is not an error.
func (b *BlobStore) Remove(storagePath string) error {
	full, err := b.resolve(storagePath)
	if err != nil {
		return err
	}
	if err := os.Remove(full); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

// RemoveProject deletes every blob stored for projectID.
func (b *BlobStore) RemoveProject(projectID int64) error {
	if projectID <= 0 {
		return errBadStoragePath
	}
	return os.RemoveAll(b.projectDir(projectID))
}

func (b *BlobStore) projectDir(projectID int64) string {
	return filepath.Join(b.dataDir, "uploads", strconv.FormatInt(projectID, 10))
}

func (b *BlobStore) resolve(storagePath string) (string, error) {
	if !storagePathRe.MatchString(storagePath) {
		return "", fmt.Errorf("%w: %q", errBadStoragePath, storagePath)
	}
	return filepath.Join(b.dataDir, filepath.FromSlash(storagePath)), nil
}
